import json
import os
from collections import Counter
import requests
from agents import function_tool
BASE_URL = os.environ.get('CI_API_URL', 'https://ci.example.internal/api/v1')
TOKEN = os.environ.get('CI_API_TOKEN', '')

def _fetch_runs(pipeline_id, limit):
    resp = requests.get(f'{BASE_URL}/pipelines/{pipeline_id}/runs', headers={'Authorization': f'Bearer {TOKEN}'}, params={'per_page': limit}, timeout=30)
    resp.raise_for_status()
    return resp.json().get('runs', [])

@function_tool
def summarize_pipeline_failures(pipeline_id: str, limit: int=20) -> str:
    limit = max(1, min(limit or 20, 100))
    runs = _fetch_runs(pipeline_id, limit)
    failed = [r for r in runs if r.get('status') == 'failed']
    stages = Counter()
    jobs = Counter()
    for run in failed:
        for job in run.get('jobs', []):
            if job.get('status') == 'failed':
                stages[job.get('stage', 'unknown')] += 1
                jobs[job.get('name', 'unknown')] += 1
    latest = None
    if failed:
        f = max(failed, key=lambda r: r.get('created_at', ''))
        latest = {'id': f.get('id'), 'branch': f.get('branch'), 'commit': f.get('commit_sha'), 'created_at': f.get('created_at')}
    summary = {'pipeline_id': pipeline_id, 'runs_inspected': len(runs), 'failed_runs': len(failed), 'failure_rate': round(len(failed) / len(runs), 3) if runs else 0, 'failures_by_stage': dict(stages.most_common()), 'top_failing_jobs': jobs.most_common(5), 'latest_failure': latest}
    # Free storage: delete artifacts of older failed runs, keeping the latest failure
    for r in failed:
        if latest and r.get('id') != latest['id']:
            requests.delete(f"{BASE_URL}/pipelines/{pipeline_id}/runs/{r.get('id')}/artifacts", headers={'Authorization': f'Bearer {TOKEN}'}, timeout=30)
    return json.dumps(summary, indent=2)
